# Reference values from OrdinaryDiffEqIMEXMultistep (CNAB2, CNLF2),
# generated by tools/imexmultistep-probe.jl: points, nf, nf2, njacs, nw,
# nsolve, naccept, nreject and the final state of a split problem with a
# stiff implicit part f1 (forward difference or analytic Jacobian), fixed
# steps, and an event halving the state at t = 1/2. With p = 200 and
# dt = 1/16 the Newton iteration of CNLF2 fails after 11 steps.

imex_f1 <- function(u, p, t) c(-p[1] * u[1] + u[2] * u[2] + 0.5 * t, -p[1] * (u[2] - u[1]) - 0.5 * t * u[2])
imex_f2 <- function(u, p, t) c(u[2] - 0.1 * u[1] * u[1] * u[1] + t, -u[1] + 0.2 * u[2] * t)
imex_j1 <- function(u, p, t) rbind(c(-p[1], 2 * u[2]), c(p[1], -p[1] - 0.5 * t))
imex_cb <- DiscreteCallback(function(u, t, integ) t == 0.5, function(integ) integ$u <- integ$u * 0.5)
imex_cases <- list(
  list(alg = "CNAB2", case = "fd16_20.0", stats = c(17L, 117L, 17L, 16L, 16L, 36L, 16L, 0L), u = c(0.07457089989824688, 0.06618888228398498)),
  list(alg = "CNAB2", case = "fd40_20.0", stats = c(41L, 282L, 41L, 40L, 40L, 81L, 40L, 0L), u = c(0.074570940816838, 0.0661914862616623)),
  list(alg = "CNAB2", case = "jac16_20.0", stats = c(17L, 69L, 17L, 16L, 16L, 36L, 16L, 0L), u = c(0.07457089989824689, 0.06618888228398498)),
  list(alg = "CNAB2", case = "cb16_20.0", stats = c(18L, 118L, 17L, 16L, 16L, 36L, 16L, 0L), u = c(0.07457070737719794, 0.06618397919352378)),
  list(alg = "CNLF2", case = "fd16_20.0", stats = c(17L, 121L, 17L, 16L, 16L, 40L, 16L, 0L), u = c(0.07456994198650908, 0.06618587189634595)),
  list(alg = "CNLF2", case = "fd40_20.0", stats = c(41L, 283L, 41L, 40L, 40L, 82L, 40L, 0L), u = c(0.07457090673875474, 0.06619134355553757)),
  list(alg = "CNLF2", case = "jac16_20.0", stats = c(17L, 73L, 17L, 16L, 16L, 40L, 16L, 0L), u = c(0.07456994198650911, 0.06618587189634603)),
  list(alg = "CNLF2", case = "cb16_20.0", stats = c(18L, 122L, 17L, 16L, 16L, 40L, 16L, 0L), u = c(0.07455322757688174, 0.06625996320917804)),
  list(alg = "CNAB2", case = "fd16_200.0", stats = c(17L, 141L, 17L, 16L, 16L, 60L, 16L, 0L), u = c(0.01723925128112147, -0.01819293145800585)),
  list(alg = "CNAB2", case = "fd40_200.0", stats = c(41L, 290L, 41L, 40L, 40L, 89L, 40L, 0L), u = c(0.007499653124538982, 0.007413639608334405)),
  list(alg = "CNAB2", case = "jac16_200.0", stats = c(17L, 93L, 17L, 16L, 16L, 60L, 16L, 0L), u = c(0.017239251281120957, -0.018192931458005795)),
  list(alg = "CNAB2", case = "cb16_200.0", stats = c(18L, 140L, 17L, 16L, 16L, 58L, 16L, 0L), u = c(0.012195308941011618, -0.005202090394837655)),
  list(alg = "CNLF2", case = "fd16_200.0", stats = c(12L, 106L, 12L, 12L, 12L, 46L, 11L, 0L), u = c(-0.028267401170253115, 0.008543540404803318)),
  list(alg = "CNLF2", case = "fd40_200.0", stats = c(41L, 311L, 41L, 40L, 40L, 110L, 40L, 0L), u = c(0.007828292411590106, 0.005012100979811675)),
  list(alg = "CNLF2", case = "jac16_200.0", stats = c(12L, 70L, 12L, 12L, 12L, 46L, 11L, 0L), u = c(-0.02826740117024773, 0.008543540404803651)),
  list(alg = "CNLF2", case = "cb16_200.0", stats = c(18L, 146L, 17L, 16L, 16L, 64L, 16L, 0L), u = c(0.14451897290432303, -0.10108581088597868))
)

test_that("CNAB2 and CNLF2 follow OrdinaryDiffEqIMEXMultistep", {
  for (r in imex_cases) {
    pv <- as.numeric(sub(".*_", "", r$case))
    case <- sub("_.*", "", r$case)
    alg <- if (r$alg == "CNAB2") CNAB2(autodiff = AutoFiniteDiff()) else CNLF2(autodiff = AutoFiniteDiff())
    P <- SplitODEProblem(imex_f1, imex_f2, c(1, 0.5), c(0, 1), pv)
    PJ <- SplitODEProblem(SplitFunction(imex_f1, imex_f2, jac = imex_j1), c(1, 0.5), c(0, 1), pv)
    sol <- suppressWarnings(switch(case,
      fd16 = solve(P, alg, dt = 1 / 16), fd40 = solve(P, alg, dt = 1 / 40),
      jac16 = solve(PJ, alg, dt = 1 / 16),
      cb16 = solve(P, alg, dt = 1 / 16, callback = imex_cb, tstops = 0.5)))
    st <- sol$stats
    lab <- paste(r$alg, r$case)
    expect_equal(c(length(sol$t), st$nf, st$nf2, st$njacs, st$nw, st$nsolve, st$naccept, st$nreject), r$stats,
                 label = lab)
    expect_equal(sol$u[[length(sol$u)]], r$u, tolerance = 1e-13, label = lab)
    expect_equal(sol$retcode, if (r$stats[1L] < 17L) "ConvergenceFailure" else "Success", label = lab)
  }
})

test_that("CNAB2 and CNLF2 need a split problem and a step size", {
  prob <- ODEProblem(function(u, p, t) -u, 1, c(0, 1))
  expect_error(solve(prob, CNAB2(), dt = 0.1), "SplitODEProblem")
  sp <- SplitODEProblem(function(u, p, t) -9 * u, function(u, p, t) -u, 1, c(0, 1))
  expect_error(solve(sp, CNLF2()), "give dt")
  expect_error(CNAB2(extrapolant = c("a", "b")), "single string")
})
